create table if not exists public.members (id integer generated by default as identity primary key, member_code text not null unique, full_name text not null, phone text not null, line_id text, created_at timestamptz not null default now());
create table if not exists public.payments (id integer generated by default as identity primary key, member_id integer not null references public.members(id), amount integer not null check(amount>0), paid_at date not null, payment_method text not null default 'cash' check(payment_method in ('cash','transfer')), slip_key text, slip_name text, slip_content_type text, recorded_by text not null, created_at timestamptz not null default now());
create table if not exists public.memberships (id integer generated by default as identity primary key, member_id integer not null references public.members(id), payment_id integer not null references public.payments(id), starts_at date not null, expires_at date not null, created_at timestamptz not null default now(), check(expires_at>=starts_at));
create table if not exists public.check_ins (id integer generated by default as identity primary key, member_id integer not null references public.members(id), checked_in_at timestamptz not null default now(), recorded_by text not null, source text not null default 'manager', reason text);
create table if not exists public.renewal_requests (id integer generated by default as identity primary key, member_id integer not null references public.members(id), status text not null default 'pending' check(status in ('pending','resolved')), requested_at timestamptz not null default now(), resolved_at timestamptz);
create table if not exists public.pt_packages (id integer generated by default as identity primary key, member_id integer not null references public.members(id), payment_id integer not null references public.payments(id), total_sessions integer not null default 14, remaining_sessions integer not null default 14, purchased_at date not null, created_at timestamptz not null default now(), check(remaining_sessions between 0 and total_sessions));
create table if not exists public.pt_sessions (id integer generated by default as identity primary key, member_id integer not null references public.members(id), package_id integer not null references public.pt_packages(id), trained_at date not null, program text, effort integer check(effort between 1 and 10), pain_note text, recorded_by text not null, created_at timestamptz not null default now());
create table if not exists public.body_assessments (id integer generated by default as identity primary key, member_id integer not null references public.members(id), assessed_at date not null, weight real, waist real, hip real, arm real, thigh real, body_fat real, muscle_mass real, goal text, note text, consent boolean not null default false, recorded_by text not null, created_at timestamptz not null default now());
create table if not exists public.follow_ups (id integer generated by default as identity primary key, member_id integer not null references public.members(id), type text not null, note text, contacted_at timestamptz not null default now(), recorded_by text not null);
create index if not exists memberships_member_idx on public.memberships(member_id,expires_at desc);
create index if not exists check_ins_member_idx on public.check_ins(member_id,checked_in_at desc);
create index if not exists renewal_requests_member_idx on public.renewal_requests(member_id,status);
create index if not exists pt_packages_member_idx on public.pt_packages(member_id);
alter table public.members enable row level security;
alter table public.payments enable row level security;
alter table public.memberships enable row level security;
alter table public.check_ins enable row level security;
alter table public.renewal_requests enable row level security;
alter table public.pt_packages enable row level security;
alter table public.pt_sessions enable row level security;
alter table public.body_assessments enable row level security;
alter table public.follow_ups enable row level security;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-evidence','payment-evidence',false,5242880,array['image/jpeg','image/png','application/pdf']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
